import 'dart:io';
import 'package:dio/dio.dart';
import 'package:flutter/material.dart';
import 'package:open_file/open_file.dart';
import 'package:path_provider/path_provider.dart';
import '../../core/network/api_client.dart';
import '../finance/finance_utils.dart';

/// Downloads the report PDF (generated by the server with the clinic letterhead)
/// and opens it in the phone's PDF viewer, where it can be shared or printed.
Future<void> openReportPdf(BuildContext context, int reportId, {String? fileName}) async {
  final messenger = ScaffoldMessenger.of(context);
  messenger.showSnackBar(const SnackBar(
    content: Text('جارٍ تجهيز التقرير...'),
    duration: Duration(seconds: 20),
  ));
  try {
    final res = await ApiClient.instance.get<List<int>>(
      '/therapist/reports/$reportId/pdf',
      options: Options(responseType: ResponseType.bytes),
    );
    final dir = await getTemporaryDirectory();
    final safe = (fileName ?? 'report-$reportId').replaceAll(RegExp(r'[^\w\-]+'), '_');
    final file = File('${dir.path}/$safe.pdf');
    await file.writeAsBytes(res.data!, flush: true);
    messenger.hideCurrentSnackBar();
    final result = await OpenFile.open(file.path, type: 'application/pdf');
    if (result.type != ResultType.done) {
      messenger.showSnackBar(const SnackBar(content: Text('لا يوجد تطبيق لفتح ملفات PDF على الجهاز')));
    }
  } catch (e) {
    messenger.hideCurrentSnackBar();
    messenger.showSnackBar(SnackBar(content: Text(apiError(e))));
  }
}
